```zig
const std = @import("std");

pub const Config = struct {
    dim: usize = 256,
    learning_rate: f32 = 0.02,
    decay: f32 = 0.995,
    surprise_threshold: f32 = 0.80,
};

pub const Tensor = struct {
    allocator: std.mem.Allocator,
    data: []f32,
    rows: usize,
    cols: usize,

    pub fn init(allocator: std.mem.Allocator, rows: usize, cols: usize) !Tensor {
        const n: usize = rows * cols;
        const data = try allocator.alloc(f32, n);
        @memset(data, 0);
        return .{ .allocator = allocator, .data = data, .rows = rows, .cols = cols };
    }

    pub fn init1D(allocator: std.mem.Allocator, n: usize) !Tensor {
        return Tensor.init(allocator, 1, n);
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.data = &[_]f32{};
        self.rows = 0;
        self.cols = 0;
    }

    pub fn len(self: Tensor) usize {
        return self.data.len;
    }

    pub fn at(self: Tensor, r: usize, c: usize) f32 {
        return self.data[r * self.cols + c];
    }

    pub fn set(self: Tensor, r: usize, c: usize, v: f32) void {
        self.data[r * self.cols + c] = v;
    }

    pub fn l2Norm(self: Tensor) f32 {
        var sum: f32 = 0;
        for (self.data) |x| sum += x * x;
        return @sqrt(sum);
    }

    pub fn copyFrom(self: Tensor, src: Tensor) !void {
        if (self.data.len != src.data.len) return error.ShapeMismatch;
        @memcpy(self.data, src.data);
    }
};

pub const SplitMix64 = struct {
    state: u64,

    pub fn init(seed: u64) SplitMix64 {
        return .{ .state = seed };
    }

    pub fn nextU64(self: *SplitMix64) u64 {
        self.state +%= 0x9E3779B97F4A7C15;
        var z = self.state;
        z = (z ^ (z >> 30)) *% 0xBF58476D1CE4E5B9;
        z = (z ^ (z >> 27)) *% 0x94D049BB133111EB;
        return z ^ (z >> 31);
    }

    pub fn nextF32(self: *SplitMix64) f32 {
        const u = self.nextU64();
        const mant: u32 = @truncate(u >> 40);
        const x: f32 = @as(f32, @floatFromInt(mant)) / 16777216.0;
        return x;
    }

    pub fn nextSignedF32(self: *SplitMix64) f32 {
        return self.nextF32() * 2.0 - 1.0;
    }
};

fn sigmoid(x: f32) f32 {
    return 1.0 / (1.0 + @exp(-x));
}

fn tanhApprox(x: f32) f32 {
    return std.math.tanh(x);
}

fn clamp(x: f32, lo: f32, hi: f32) f32 {
    return @min(hi, @max(lo, x));
}

fn matVecMul(out: Tensor, mat: Tensor, vec: Tensor) !void {
    if (out.rows != 1) return error.ShapeMismatch;
    if (vec.rows != 1) return error.ShapeMismatch;
    if (mat.rows != out.cols) return error.ShapeMismatch;
    if (mat.cols != vec.cols) return error.ShapeMismatch;

    const dim = out.cols;
    var i: usize = 0;
    while (i < dim) : (i += 1) {
        var sum: f32 = 0;
        var j: usize = 0;
        while (j < dim) : (j += 1) {
            sum += mat.at(i, j) * vec.at(0, j);
        }
        out.set(0, i, sum);
    }
}

fn outerAccumulate(mat: Tensor, x: Tensor, scale: f32) !void {
    if (mat.rows != mat.cols) return error.ShapeMismatch;
    if (x.rows != 1) return error.ShapeMismatch;
    if (x.cols != mat.rows) return error.ShapeMismatch;

    const dim = mat.rows;
    var i: usize = 0;
    while (i < dim) : (i += 1) {
        const xi = x.at(0, i);
        var j: usize = 0;
        while (j < dim) : (j += 1) {
            const v = mat.at(i, j) + scale * xi * x.at(0, j);
            mat.set(i, j, v);
        }
    }
}

fn matScaleInPlace(mat: Tensor, scale: f32) void {
    for (mat.data) |*v| v.* *= scale;
}

pub const KalmarGate = struct {
    allocator: std.mem.Allocator,
    w_and: Tensor,
    w_or: Tensor,
    bias: Tensor,

    pub fn init(allocator: std.mem.Allocator, dim: usize, seed: u64) !KalmarGate {
        var prng = SplitMix64.init(seed);
        var w_and = try Tensor.init1D(allocator, dim);
        var w_or = try Tensor.init1D(allocator, dim);
        var bias = try Tensor.init1D(allocator, dim);

        var i: usize = 0;
        while (i < dim) : (i += 1) {
            w_and.data[i] = 0.5 + 0.02 * prng.nextSignedF32();
            w_or.data[i] = 0.5 + 0.02 * prng.nextSignedF32();
            bias.data[i] = 0.01 * prng.nextSignedF32();
        }

        return .{ .allocator = allocator, .w_and = w_and, .w_or = w_or, .bias = bias };
    }

    pub fn deinit(self: *KalmarGate) void {
        self.w_and.deinit();
        self.w_or.deinit();
        self.bias.deinit();
    }

    pub fn forward(self: *KalmarGate, input: Tensor) !Tensor {
        if (input.rows != 1) return error.ShapeMismatch;
        if (input.cols != self.w_and.cols) return error.ShapeMismatch;

        var out = try Tensor.init1D(self.allocator, input.cols);
        const n = input.cols;

        var i: usize = 0;
        while (i < n) : (i += 1) {
            const x = input.at(0, i);
            const wa = self.w_and.at(0, i);
            const wo = self.w_or.at(0, i);

            const val_and = @max(0.0, x + wa - 1.0);
            const val_or = x + wo - (x * wo);

            const gate = sigmoid(x - 0.5);
            const y = gate * val_and + (1.0 - gate) * val_or + self.bias.at(0, i);

            out.set(0, i, y);
        }

        return out;
    }
};

pub const RieszMemory = struct {
    allocator: std.mem.Allocator,
    state: Tensor,
    tmp: Tensor,
    cfg: Config,

    pub fn init(allocator: std.mem.Allocator, cfg: Config, seed: u64) !RieszMemory {
        var prng = SplitMix64.init(seed);
        var state = try Tensor.init(allocator, cfg.dim, cfg.dim);
        var tmp = try Tensor.init1D(allocator, cfg.dim);

        var i: usize = 0;
        while (i < state.len()) : (i += 1) {
            state.data[i] = 0.0005 * prng.nextSignedF32();
        }

        return .{ .allocator = allocator, .state = state, .tmp = tmp, .cfg = cfg };
    }

    pub fn deinit(self: *RieszMemory) void {
        self.state.deinit();
        self.tmp.deinit();
    }

    pub fn reconstruct(self: *RieszMemory, x: Tensor) !Tensor {
        var out = try Tensor.init1D(self.allocator, self.cfg.dim);
        try matVecMul(out, self.state, x);
        var i: usize = 0;
        while (i < out.cols) : (i += 1) out.data[i] = tanhApprox(out.data[i]);
        return out;
    }

    pub fn surprise(self: *RieszMemory, x: Tensor) !f32 {
        const recon = try self.reconstruct(x);
        defer recon.deinit();

        var err: f32 = 0;
        var i: usize = 0;
        while (i < x.cols) : (i += 1) {
            const d = x.at(0, i) - recon.at(0, i);
            err += d * d;
        }
        err = @sqrt(err / @as(f32, @floatFromInt(x.cols)));
        return clamp(sigmoid(3.0 * err), 0.0, 1.0);
    }

    pub fn updateTTT(self: *RieszMemory, x: Tensor, s: f32) !void {
        const eta = self.cfg.learning_rate * (0.25 + 0.75 * s);
        matScaleInPlace(self.state, self.cfg.decay);
        try outerAccumulate(self.state, x, eta);
    }

    pub fn retrieve(self: *RieszMemory, x: Tensor) !Tensor {
        var out = try Tensor.init1D(self.allocator, self.cfg.dim);
        try matVecMul(out, self.state, x);
        var i: usize = 0;
        while (i < out.cols) : (i += 1) out.data[i] = tanhApprox(out.data[i]);
        return out;
    }
};

pub const KRFAAgent = struct {
    allocator: std.mem.Allocator,
    cfg: Config,
    logic: KalmarGate,
    memory: RieszMemory,

    pub fn init(allocator: std.mem.Allocator, cfg: Config, seed: u64) !KRFAAgent {
        const logic = try KalmarGate.init(allocator, cfg.dim, seed ^ 0xA5A5A5A5A5A5A5A5);
        const memory = try RieszMemory.init(allocator, cfg, seed ^ 0xC3C3C3C3C3C3C3C3);
        return .{ .allocator = allocator, .cfg = cfg, .logic = logic, .memory = memory };
    }

    pub fn deinit(self: *KRFAAgent) void {
        self.logic.deinit();
        self.memory.deinit();
    }

    pub fn process(self: *KRFAAgent, token_vec: Tensor) !struct { out: Tensor, surprise: f32, agent_mode: bool } {
        if (token_vec.rows != 1) return error.ShapeMismatch;
        if (token_vec.cols != self.cfg.dim) return error.ShapeMismatch;

        const s = try self.memory.surprise(token_vec);
        try self.memory.updateTTT(token_vec, s);

        const ctx = try self.memory.retrieve(token_vec);
        defer ctx.deinit();

        var fused = try Tensor.init1D(self.allocator, self.cfg.dim);
        defer fused.deinit();

        var i: usize = 0;
        while (i < self.cfg.dim) : (i += 1) {
            fused.data[i] = token_vec.data[i] + ctx.data[i];
        }

        const out = try self.logic.forward(fused);
        const agent_mode = s > self.cfg.surprise_threshold;

        return .{ .out = out, .surprise = s, .agent_mode = agent_mode };
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const cfg = Config{ .dim = 256, .learning_rate = 0.02, .decay = 0.995, .surprise_threshold = 0.80 };
    var agent = try KRFAAgent.init(allocator, cfg, 0x1234_5678_9ABC_DEF0);
    defer agent.deinit();

    var x = try Tensor.init1D(allocator, cfg.dim);
    defer x.deinit();

    var i: usize = 0;
    while (i < cfg.dim) : (i += 1) {
        x.data[i] = @as(f32, @floatFromInt(i % 17)) / 17.0;
    }

    const r = try agent.process(x);
    defer r.out.deinit();

    const stdout = std.io.getStdOut().writer();
    try stdout.print("out_norm={d:.6} surprise={d:.6} agent_mode={}\n", .{ r.out.l2Norm(), r.surprise, r.agent_mode });
}
