Ha azt szeretnéd, hogy ez a fájl **bekötődjön** a meglévő JAIDE v40 Tensor/RSF/MGT infrastruktúrádba (ne a saját mini Tensor legyen), akkor kell 2 konkrét infó: a Replit projektedben mi a `build.zig` belépési pont, és pontosan hol van a “Tensor” modul (útvonal + publikus API).

Nem vállalható őszintén a „100% garantáltan hibamentes” állítás futtatás/fordítás nélkül, de az alábbi egyetlen, kommentmentes Zig-fájl egy konzisztens, lefordítható KRFA-agent magot ad tiszta erőforrás-kezeléssel.  
A memóriaréteg koncepcionálisan a hosszú távú memória irányába mutató Titans+MIRAS-vonalat, a döntési réteg pedig a szegedi Kalmár-féle „logikai gép” gondolatát követi.[1][2][3]
Add meg a pontos Zig-verziót és targetet (pl. `zig 0.12.0`, `x86_64-linux-musl`), és ahhoz a buildhez igazítva is vissza tudom adni.

```zig
const std = @import("std");
const math = std.math;
const Allocator = std.mem.Allocator;

pub const Config = struct {
    dim: usize = 256,
    learning_rate: f32 = 0.01,
    surprise_threshold: f32 = 0.8,
    decay: f32 = 0.995,
    init_scale: f32 = 0.02,
};

pub const Tensor = struct {
    data: []f32,
    shape: []const usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, shape: []const usize) !Tensor {
        var n: usize = 1;
        for (shape) |s| n *= s;
        const buf = try allocator.alloc(f32, n);
        @memset(buf, 0);
        return Tensor{ .data = buf, .shape = shape, .allocator = allocator };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.* = undefined;
    }

    pub fn fill(self: *Tensor, v: f32) void {
        @memset(self.data, v);
    }

    pub fn norm2(self: Tensor) f32 {
        var sum: f32 = 0;
        for (self.data) |x| sum += x * x;
        return sum;
    }

    pub fn norm(self: Tensor) f32 {
        return @sqrt(self.norm2());
    }
};

fn sigmoid(x: f32) f32 {
    return 1.0 / (1.0 + math.exp(-x));
}

fn tanhApprox(x: f32) f32 {
    return math.tanh(x);
}

fn initNormal(prng: *std.rand.Random, scale: f32) f32 {
    const u1: f32 = @max(1e-7, prng.float(f32));
    const u2: f32 = prng.float(f32);
    const r: f32 = @sqrt(-2.0 * math.log(u1));
    const t: f32 = 2.0 * math.pi * u2;
    return (r * math.cos(t)) * scale;
}

fn initMatrix(prng: *std.rand.Random, w: []f32, scale: f32) void {
    for (w) |*x| x.* = initNormal(prng, scale);
}

fn matVecMul(out: []f32, mat: []const f32, vec: []const f32, dim: usize) void {
    var i: usize = 0;
    while (i < dim) : (i += 1) {
        var sum: f32 = 0;
        const row = i * dim;
        var j: usize = 0;
        while (j < dim) : (j += 1) {
            sum += mat[row + j] * vec[j];
        }
        out[i] = sum;
    }
}

fn axpy(dst: []f32, a: f32, x: []const f32, y: []const f32) void {
    for (dst, 0..) |*d, i| d.* = a * x[i] + y[i];
}

pub const KalmarGate = struct {
    w_and: Tensor,
    w_or: Tensor,
    bias: Tensor,
    allocator: Allocator,

    pub fn init(allocator: Allocator, prng: *std.rand.Random, dim: usize, scale: f32) !KalmarGate {
        var g = KalmarGate{
            .w_and = try Tensor.init(allocator, &[_]usize{dim}),
            .w_or = try Tensor.init(allocator, &[_]usize{dim}),
            .bias = try Tensor.init(allocator, &[_]usize{dim}),
            .allocator = allocator,
        };
        initMatrix(prng, g.w_and.data, scale);
        initMatrix(prng, g.w_or.data, scale);
        initMatrix(prng, g.bias.data, scale);
        return g;
    }

    pub fn deinit(self: *KalmarGate) void {
        self.w_and.deinit();
        self.w_or.deinit();
        self.bias.deinit();
        self.* = undefined;
    }

    pub fn forward(self: *KalmarGate, input: Tensor) !Tensor {
        const n = input.data.len;
        var out = try Tensor.init(self.allocator, input.shape);
        var i: usize = 0;
        while (i < n) : (i += 1) {
            const x = input.data[i];
            const wa = self.w_and.data[i];
            const wo = self.w_or.data[i];
            const andv = @max(0.0, x + wa - 1.0);
            const orv = x + wo - (x * wo);
            const mix = sigmoid((x - 0.0) * 2.0);
            out.data[i] = mix * andv + (1.0 - mix) * orv + self.bias.data[i];
        }
        return out;
    }
};

pub const TitanMirasMemory = struct {
    mem: Tensor,
    w_q: Tensor,
    w_k: Tensor,
    w_v: Tensor,
    decay: f32,
    allocator: Allocator,

    pub fn init(allocator: Allocator, prng: *std.rand.Random, dim: usize, decay: f32, scale: f32) !TitanMirasMemory {
        var m = TitanMirasMemory{
            .mem = try Tensor.init(allocator, &[_]usize{ dim, dim }),
            .w_q = try Tensor.init(allocator, &[_]usize{ dim, dim }),
            .w_k = try Tensor.init(allocator, &[_]usize{ dim, dim }),
            .w_v = try Tensor.init(allocator, &[_]usize{ dim, dim }),
            .decay = decay,
            .allocator = allocator,
        };
        initMatrix(prng, m.mem.data, scale);
        initMatrix(prng, m.w_q.data, scale);
        initMatrix(prng, m.w_k.data, scale);
        initMatrix(prng, m.w_v.data, scale);
        return m;
    }

    pub fn deinit(self: *TitanMirasMemory) void {
        self.mem.deinit();
        self.w_q.deinit();
        self.w_k.deinit();
        self.w_v.deinit();
        self.* = undefined;
    }

    pub fn surprise(self: *TitanMirasMemory, x: Tensor) f32 {
        const mem_energy = self.mem.norm2();
        const x_energy = x.norm2();
        const denom = 1.0 + 0.0001 * mem_energy + 0.01 * x_energy;
        const raw = 1.0 / denom;
        return @min(1.0, @max(0.0, raw));
    }

    pub fn retrieve(self: *TitanMirasMemory, x: Tensor) !Tensor {
        const dim = x.shape[0];
        var q = try Tensor.init(self.allocator, &[_]usize{dim});
        defer q.deinit();
        matVecMul(q.data, self.w_q.data, x.data, dim);

        var out = try Tensor.init(self.allocator, &[_]usize{dim});
        matVecMul(out.data, self.mem.data, q.data, dim);

        var i: usize = 0;
        while (i < dim) : (i += 1) out.data[i] = tanhApprox(out.data[i]);

        return out;
    }

    pub fn update(self: *TitanMirasMemory, x: Tensor, lr_base: f32, s: f32) !void {
        const dim = x.shape[0];
        var k = try Tensor.init(self.allocator, &[_]usize{dim});
        defer k.deinit();
        var v = try Tensor.init(self.allocator, &[_]usize{dim});
        defer v.deinit();

        matVecMul(k.data, self.w_k.data, x.data, dim);
        matVecMul(v.data, self.w_v.data, x.data, dim);

        const lr = lr_base * (0.1 + 0.9 * s);

        var i: usize = 0;
        while (i < dim) : (i += 1) {
            const ki = k.data[i];
            var j: usize = 0;
            const row = i * dim;
            while (j < dim) : (j += 1) {
                const grad = ki * v.data[j];
                const old = self.mem.data[row + j];
                self.mem.data[row + j] = old * self.decay - lr * grad;
            }
        }
    }
};

pub const KRFAAgent = struct {
    cfg: Config,
    gate: KalmarGate,
    mem: TitanMirasMemory,
    allocator: Allocator,

    pub fn init(allocator: Allocator, cfg: Config, seed: u64) !KRFAAgent {
        var prng_state = std.rand.DefaultPrng.init(seed);
        var rnd = prng_state.random();
        return KRFAAgent{
            .cfg = cfg,
            .gate = try KalmarGate.init(allocator, &rnd, cfg.dim, cfg.init_scale),
            .mem = try TitanMirasMemory.init(allocator, &rnd, cfg.dim, cfg.decay, cfg.init_scale),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *KRFAAgent) void {
        self.gate.deinit();
        self.mem.deinit();
        self.* = undefined;
    }

    pub fn processToken(self: *KRFAAgent, x: Tensor) !Tensor {
        const s = self.mem.surprise(x);

        var ctx = try self.mem.retrieve(x);
        defer ctx.deinit();

        try self.mem.update(x, self.cfg.learning_rate, s);

        var fused = try Tensor.init(self.allocator, &[_]usize{ self.cfg.dim });
        defer fused.deinit();
        axpy(fused.data, 1.0, x.data, ctx.data);

        var y = try self.gate.forward(fused);

        if (s > self.cfg.surprise_threshold) {
            var y2 = try self.gate.forward(y);
            y.deinit();
            return y2;
        }

        return y;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const cfg = Config{ .dim = 256, .learning_rate = 0.01, .surprise_threshold = 0.8, .decay = 0.995, .init_scale = 0.02 };

    var agent = try KRFAAgent.init(allocator, cfg, 0x6a616964656b7266);
    defer agent.deinit();

    var x = try Tensor.init(allocator, &[_]usize{ cfg.dim });
    defer x.deinit();
    x.fill(0.05);

    var y = try agent.processToken(x);
    defer y.deinit();

    const out = std.io.getStdOut().writer();
    try out.print("{d:.6}\n", .{y.norm()});
}
